/** The procedural gate brick that carries `component`, if any. */
export function proceduralGateForComponent(
  component: string
): ProceduralGate | undefined {
  for (const g of PROCEDURAL_GATES.values())
    if (g.component === component) return g;
  return undefined;
}

/** The smallest variant of `asset` that physically exposes every port in `ports`. */
export function smallestGateVariant(
  asset: string,
  ports: readonly string[]
): GateVariant | undefined {
  return PROCEDURAL_GATES.get(asset)?.variants.find(v =>
    ports.every(p => v.ports.includes(p))
  );
}
